<?php
declare(strict_types=1);require_once __DIR__.'/config/purchase_step14.php';$error=null;$supplier=null;$bills=[];$receipts=[];$payments=[];$returns=[];$id=(int)($_GET['id']??0);
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];$supplier=purchase_step14_supplier($pdo,$orgId,$id);foreach(purchase_step14_bill_rows($pdo,$orgId,'all') as $b)if((int)$b['supplier_id']===$id)$bills[]=$b;$stmt=$pdo->prepare("SELECT r.*,b.invoice_number FROM purchase_receipts r JOIN purchase_bills b ON b.id=r.purchase_bill_id AND b.organization_id=r.organization_id WHERE r.organization_id=? AND r.supplier_id=? ORDER BY r.receipt_date DESC,r.id DESC");$stmt->execute([$orgId,$id]);$receipts=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT p.*,b.invoice_number FROM purchase_payments p JOIN purchase_bills b ON b.id=p.purchase_bill_id AND b.organization_id=p.organization_id WHERE p.organization_id=? AND p.supplier_id=? ORDER BY p.payment_date DESC,p.id DESC");$stmt->execute([$orgId,$id]);$payments=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT r.*,b.invoice_number FROM purchase_returns r JOIN purchase_bills b ON b.id=r.purchase_bill_id AND b.organization_id=r.organization_id WHERE r.organization_id=? AND r.supplier_id=? ORDER BY r.return_date DESC,r.id DESC");$stmt->execute([$orgId,$id]);$returns=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function sd_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sd_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
$total=0;$ret=0;$paid=0;$out=0;foreach($bills as $b){if($b['status']!=='active')continue;$total+=(float)$b['total_amount'];$ret+=(float)$b['return_credit'];$paid+=(float)$b['paid_amount'];$out+=(float)$b['outstanding'];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Supplier History - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="supplier_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Supplier 360°</small></span></a><div class="os-top-actions"><a class="os-btn" href="supplier_center.php">Suppliers</a><a class="os-btn" href="purchase_bills.php">Bills</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Supplier</div><nav class="os-nav"><a href="supplier_center.php"><i class="dot"></i>Supplier Master</a><a class="active" href="#"><i class="dot"></i>Supplier 360°</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><?php if($error):?><div class="pp-alert bad"><strong>Supplier history diagnostic:</strong> <?= sd_h($error) ?></div><?php else:?><section class="os-hero pp-hero"><div class="os-kicker">SUPPLIER 360° • #<?= $id ?></div><h1><?= sd_h($supplier['supplier_name']) ?></h1><p><?= sd_h($supplier['supplier_code']) ?><?= $supplier['mobile']?' • '.$supplier['mobile']:'' ?><?= $supplier['gstin']?' • GSTIN '.$supplier['gstin']:'' ?></p><div class="os-status-row"><span class="os-chip good"><?= sd_h(strtoupper($supplier['status'])) ?></span><span class="os-chip"><?= count($bills) ?> bills</span><span class="os-chip"><?= count($receipts) ?> receipts</span><span class="os-chip"><?= count($payments) ?> payments</span><span class="os-chip"><?= count($returns) ?> returns</span></div></section><section class="s10-kpis" style="margin-top:14px"><div class="s10-kpi"><small>Billed</small><strong><?= sd_m($total) ?></strong></div><div class="s10-kpi"><small>Return Credit</small><strong><?= sd_m($ret) ?></strong></div><div class="s10-kpi"><small>Paid</small><strong><?= sd_m($paid) ?></strong></div><div class="s10-kpi"><small>Outstanding</small><strong><?= sd_m($out) ?></strong></div></section><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-7"><h2>Bill History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Return</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody><?php foreach($bills as $b):?><tr><td><a href="purchase_bills.php?bill=<?= (int)$b['id'] ?>"><b><?= sd_h($b['invoice_number']) ?></b></a></td><td><?= sd_h($b['invoice_date']) ?></td><td><?= sd_m($b['total_amount']) ?></td><td><?= sd_m($b['return_credit']) ?></td><td><?= sd_m($b['paid_amount']) ?></td><td><b><?= sd_m($b['outstanding']) ?></b></td></tr><?php endforeach;?><?php if(!$bills):?><tr><td colspan="6">No bills.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-5"><h2>Supplier Profile</h2><div class="s10-list"><div class="s10-row"><div><b>Contact</b><small><?= sd_h($supplier['contact_person']?:'—') ?></small></div></div><div class="s10-row"><div><b>Mobile / Email</b><small><?= sd_h(($supplier['mobile']?:'—').' • '.($supplier['email']?:'—')) ?></small></div></div><div class="s10-row"><div><b>Payment Terms</b><small><?= (int)$supplier['payment_terms_days'] ?> days</small></div></div><div class="s10-row"><div><b>Address</b><small><?= sd_h($supplier['address_text']?:'—') ?></small></div></div></div></article><article class="os-card pp-span-6"><h2>Goods Receipts</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>GRN</th><th>Invoice</th></tr></thead><tbody><?php foreach($receipts as $r):?><tr><td><?= sd_h($r['receipt_date']) ?></td><td><?= sd_h($r['receipt_number']) ?></td><td><?= sd_h($r['invoice_number']) ?></td></tr><?php endforeach;?><?php if(!$receipts):?><tr><td colspan="3">No receipts.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-6"><h2>Returns / Payments</h2><div class="s10-list"><?php foreach($returns as $r):?><div class="s10-row"><div><b><?= sd_h($r['return_number']) ?></b><small><?= sd_h($r['return_date'].' • '.$r['invoice_number']) ?></small></div><strong><?= sd_m($r['total_credit']) ?></strong></div><?php endforeach;?><?php foreach(array_slice($payments,0,8) as $p):?><div class="s10-row"><div><b>Payment #<?= (int)$p['id'] ?></b><small><?= sd_h($p['payment_date'].' • '.$p['invoice_number'].' • '.$p['status']) ?></small></div><strong><?= sd_m($p['amount']) ?></strong></div><?php endforeach;?></div></article></section><?php endif;?><div class="os-footer-note"><strong>Supplier trace:</strong> profile, bills, goods receipts, payments and returns remain linked to the same supplier ID.</div></main></div></body></html>